import{_ as d,C as a,o as s,c as n,a5 as o,E as i}from"./chunks/framework.D2XEhk-n.js";const g=JSON.parse('{"title":"Module map","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"reference/module-map.md","filePath":"reference/module-map.md","lastUpdated":1790626046000}'),l={name:"reference/module-map.md"};function c(r,e,u,h,p,_){const t=a("ModuleGraph");return s(),n("div",null,[e[0]||(e[0]=o('<h1 id="module-map" tabindex="-1">Module map <a class="header-anchor" href="#module-map" aria-label="Permalink to &quot;Module map&quot;">​</a></h1><p><strong>Every JUCE module and every dependency between them, generated at build time from the <code>BEGIN_JUCE_MODULE_DECLARATION</code> blocks in <code>modules/*/juce_*.h</code>.</strong> Columns are <em>layers</em>: a module&#39;s layer is the length of its longest dependency chain down to <code>juce_core</code>.</p><p>Click (or tab to and press Enter on) a module to highlight what it <strong>depends on</strong> (blue) and what is <strong>built on it</strong> (orange). Use the chips to hide groups.</p>',3)),i(t),e[1]||(e[1]=o('<h2 id="reading-the-graph" tabindex="-1">Reading the graph <a class="header-anchor" href="#reading-the-graph" aria-label="Permalink to &quot;Reading the graph&quot;">​</a></h2><ul><li><strong>Left means fundamental.</strong> <code>juce_core</code> (layer 0) is needed by everything; nothing depends on the rightmost modules.</li><li><strong>Linking pulls in the whole upstream chain.</strong> Add <code>juce::juce_audio_utils</code> to a CMake target and you get it plus the 11 modules beneath it. Selecting a module shows this &quot;pulls in&quot; count.</li><li><strong>Two independent trunks.</strong> The audio chain (<code>audio_basics → audio_devices / audio_formats → dsp</code>) never touches the GUI chain (<code>graphics → gui_basics → gui_extra</code>). They only meet in <code>juce_audio_processors</code> and <code>juce_audio_utils</code>.</li><li><strong><code>juce_events</code> is the junction.</strong> Almost every branch passes through it, because almost everything needs the message loop.</li><li><strong>Some modules are leaves</strong> (<code>juce_dsp</code>, <code>juce_osc</code>, <code>juce_midi_ci</code>, <code>juce_javascript</code>, <code>juce_video</code>, <code>juce_opengl</code>…). You can add or skip them freely.</li></ul><h2 id="questions-to-explore" tabindex="-1">Questions to explore <a class="header-anchor" href="#questions-to-explore" aria-label="Permalink to &quot;Questions to explore&quot;">​</a></h2><ol><li>Which module would you need for a command-line tool that converts WAV files to FLAC? What does it pull in?</li><li>Why does <code>juce_dsp</code> depend on <code>juce_audio_formats</code>? (Hint: look at <code>dsp::Convolution::loadImpulseResponse</code>.)</li><li><code>juce_audio_processors_headless</code> pulls in only three modules. What kinds of program does that make possible that <code>juce_audio_processors</code> (which pulls in the whole GUI stack) did not?</li></ol>',4))])}const f=d(l,[["render",c]]);export{g as __pageData,f as default};
